-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    hl.exec_cmd("systemctl --user start hyprland-session.target")

    -- Polkit authentication agent. Without one, anything needing elevation
    -- (nemo mounting a disk, gparted, etc.) fails silently: polkitd is running
    -- but has no agent to raise a password prompt through.
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("awww-daemon")

    -- Headless output for remote streaming. Fires once per Hyprland start (not
    -- on reload), so it will not stack up HEADLESS-2, -3 ... on every reload.
    -- Also re-points Sunshine's output_name at the name the output actually got.
    hl.exec_cmd("~/.local/bin/remote-display up")

    -- Watchdog owns the hyprpanel lifecycle: spawns it as a child (so gdb can
    -- attach via ptrace_scope=1), monitors the heartbeat file, and restarts on
    -- freeze with a circuit breaker. hyprpanel-launch is no longer wired here so
    -- the watchdog is the sole parent.
    hl.exec_cmd("~/.config/hyprpanel/bin/hyprpanel-watchdog")

    hl.exec_cmd("spotify --remote-debugging-port=9222")
    hl.exec_cmd("discord")
    hl.exec_cmd("notion-app")
    hl.exec_cmd("mullvad-vpn")
    hl.exec_cmd("~/.local/bin/hyprsunset-auto")
    hl.exec_cmd("sleep 5 && claude-desktop")
    hl.exec_cmd("/home/archie/Documents/Github-Projects/ycombo/ycombo-start.sh --hidden")
end)

-- A reload re-applies monitor config from this file, and this file deliberately
-- does not declare the headless output, so a reload resets it to the 1920x1080
-- default. Re-assert it afterwards. remote-display is idempotent: it reuses the
-- existing output rather than creating another one.
hl.on("config.reloaded", function()
    hl.exec_cmd("~/.local/bin/remote-display up")
end)


