-- Dynamic gaps for ultrawide: decrease side gaps as tiled window count increases.
-- Scoped to DP-2 with m[...]: these side gaps are sized for a 5120px monitor and
-- would leave ~150px of usable width on the 1512px logical headless output.
hl.workspace_rule({ workspace = "m[DP-2] w[t1-2]",  gaps_out = { top = 20, right = 680, bottom = 20, left = 680 } })
hl.workspace_rule({ workspace = "m[DP-2] w[t3-4]",  gaps_out = { top = 20, right = 340, bottom = 20, left = 340 } })
hl.workspace_rule({ workspace = "m[DP-2] w[t5-99]", gaps_out = { top = 20, right = 154, bottom = 20, left = 154 } })

-- Workspace 10 (SUPER+0) is the remote workspace; remote-display pins it to the
-- headless output once that output exists and its name is known. Pinning 1-9 to
-- DP-2 here has to happen in config rather than in the script, because it must
-- be loaded before the headless output is created — otherwise the new output
-- claims workspace 1 and SUPER+1 starts focusing a screen that is not there.
for i = 1, 9 do
    hl.workspace_rule({ workspace = tostring(i), monitor = "DP-2" })
end


